# Generated by roundhouse --target futamura: whole-route replacement.
#
# The app's `--target ruby` emit (vendor/futamura/lowered) runs inside
# this Rails process, loaded into a Ruby::Box so its runtime's
# ActiveRecord / ActionController / ActiveSupport are separate constants
# from Rails' own. A middleware just after Rails' session store hands a
# GET to the lowered dispatcher when the route's action is one the
# analysis cleared (config/initializers/futamura_routes.rb lists them);
# every other request, and any request the lowered app declines, is
# Rails'.
#
# What crosses the boundary:
#   * the session, as a Hash of its String values, and the flash; the
#     lowered app's changes are written back into Rails' session, which
#     Rails' own store persists. Nothing is signed or verified twice.
#   * the database connection: Rails' own, checked out of its pool for
#     the request and lent to the lowered runtime (Db.with_lent_connection).
#     A box loads its own copy of every native extension, so the lowered
#     app opening the database file itself would put two SQLite
#     libraries on one file in one process. Lending the connection keeps
#     one library, one connection, and Rails' open transaction (a test's
#     fixtures) in view.
# No model object built on one side reaches the other.
#
# Not shared: Rails.cache. The lowered app keeps its own in-memory store;
# a key Rails deletes stays cached on the lowered side until it expires.
#
# Requires Ruby 4.1 (Ruby::Box) with RUBY_BOX=1 set before the process
# starts, and SQLite (on another database it turns itself off).
# FUTAMURA_WHOLE_ROUTE=off serves everything from Rails.
require "set"

module Futamura
  module WholeRoute
    @box = nil
    @actions = nil
    @stats = Hash.new(0)

    class << self
      attr_reader :box, :actions, :stats

      def enabled?
        ENV["FUTAMURA_WHOLE_ROUTE"] != "off"
      end

      def install(app, root, actions)
        return unless enabled?
        # The lowered runtime reads through the connection Rails lends it,
        # and only its SQLite shim can take one. On any other database
        # every route stays Rails' (and no box is needed).
        adapter = primary_adapter(app)
        unless adapter.to_s.start_with?("sqlite")
          warn "futamura: whole-route replacement is off: it supports SQLite only, and the primary database is #{adapter.inspect}"
          return
        end
        unless defined?(Ruby::Box) && Ruby::Box.respond_to?(:enabled?) && Ruby::Box.enabled?
          raise "futamura: whole-route replacement needs Ruby::Box: Ruby 4.1 or newer, started with " \
                "RUBY_BOX=1 (or set FUTAMURA_WHOLE_ROUTE=off to serve every route from Rails)"
        end
        @actions = Set.new(actions).freeze
        store = app.config.session_store
        if store
          app.config.middleware.insert_after store, Middleware
        else
          app.config.middleware.use Middleware
        end
        app.config.after_initialize { Futamura::WholeRoute.boot(root) }
        at_exit { warn "futamura whole-route: #{@stats.sort_by { |_, v| -v }.to_h}" } if ENV["FUTAMURA_STATS"]
      end

      def primary_adapter(app)
        config = app.config.database_configuration[Rails.env.to_s] || {}
        config["adapter"] || config.dig("primary", "adapter")
      rescue StandardError
        nil
      end

      def boot(root)
        box = Ruby::Box.new
        box.eval(<<~RUBY)
          require #{File.join(root, "main").inspect}
          ActiveRecord.adapter = SqliteAdapter
          # The app's own log lines (`Rails.logger.info` in a filter) go
          # where Rails sends its own: Rails' logger, at Rails' level.
          module Rails
            class << self
              attr_accessor :host_logger
            end
            def self.log_line(line)
              host_logger ? host_logger.info(line) : warn(line)
            end
          end
        RUBY
        box::Rails.host_logger = ::Rails.logger
        @box = box
      end
    end

    class Middleware
      def initialize(app)
        @app = app
      end

      def call(env)
        box = WholeRoute.box
        return @app.call(env) unless box && env["REQUEST_METHOD"] == "GET"

        session = env["rack.session"]
        before = {}
        session&.to_hash&.each { |k, v| before[k.to_s] = v if v.is_a?(String) }
        flash = flash_in(session)
        lowered = env.dup
        lowered["roundhouse.actions"] = WholeRoute.actions
        lowered["roundhouse.session"] = before
        lowered["roundhouse.flash"] = flash

        status, headers, body = begin
          ActiveRecord::Base.connection_pool.with_connection do |conn|
            conn.materialize_transactions
            box::Db.with_lent_connection(conn.raw_connection) { box::Main.run_rack(lowered) }
          end
        rescue StandardError => e
          WholeRoute.stats["raised #{e.class}"] += 1
          Rails.logger.warn("futamura: lowered #{env['PATH_INFO']} raised #{e.class}: #{e.message}; served by Rails")
          return @app.call(env)
        end

        if lowered["roundhouse.declined"]
          WholeRoute.stats["rails"] += 1
          return @app.call(env)
        end
        if status == 404 || status >= 500
          WholeRoute.stats["fallback #{status}"] += 1
          Rails.logger.warn("futamura: lowered #{env['PATH_INFO']} answered #{status}; served by Rails") if status >= 500
          return @app.call(env)
        end
        WholeRoute.stats["lowered"] += 1
        write_back(session, before, lowered)
        flash_out(session, flash, lowered["roundhouse.flash.out"])
        [status, headers, body]
      end

      private

      # Rails keeps the flash in the session as {"discard" => [...],
      # "flashes" => {...}}; what was not discarded is this request's.
      def flash_in(session)
        value = session && session["flash"]
        return {} unless value.is_a?(Hash)
        discard = Array(value["discard"]).map(&:to_s)
        (value["flashes"] || {}).each_with_object({}) do |(k, v), out|
          out[k.to_s] = v if v.is_a?(String) && !discard.include?(k.to_s)
        end
      end

      def flash_out(session, inbound, persisted)
        return if session.nil? || (inbound.empty? && (persisted.nil? || persisted.empty?))
        if persisted.nil? || persisted.empty?
          session.delete("flash")
        else
          session["flash"] = { "discard" => [], "flashes" => persisted.to_h }
        end
      end

      def write_back(session, before, lowered)
        after = lowered["roundhouse.session.out"] or return
        return if session.nil?
        after.each { |k, v| session[k] = v unless before[k.to_s] == v }
        (before.keys - after.keys.map(&:to_s)).each { |k| session.delete(k) }
        WholeRoute.stats["session writes"] += 1
      end
    end
  end
end
